for _schema in COMPOUND_TOOL_SCHEMAS:
    _fn = _schema.get("function", {})
    if _fn.get("name") == "gui":
        _fn["description"] += (
            "\nCompatibility: if the model passes action='open' with target/name, "
            "the runtime routes it to app.open. If it passes action='click' with "
            "target/label/text but no x/y, the runtime routes it to click_button."
        )
    elif _fn.get("name") == "computer_use":
        _fn["description"] += (
            "\nBrowser chains: use computer_use for goals like opening/focusing a "
            "browser and then clicking a bookmark/favorite/link/result/control; "
            "pass the full natural-language goal."
        )
    elif _fn.get("name") == "media":
        _fn["description"] += (
            "\nCurrent media: when the user asks to resume/continue/play the "
            "current video or media without naming a new title/search target, "
            "use action='resume' or play_pause. Do not invent a YouTube query "
            "such as the last watched video; query is for named content."
        )
